// Example of Monomorphic (Fast) vs Polymorphic (Slow)

function getX(obj) {
  return obj.x; // V8 optimizes this if 'obj' always has the same shape
}

// Fast: Same Shape (Hidden Class)
getX({ x: 1, y: 2 });
getX({ x: 5, y: 10 });

// Slow: Different Shape causes De-optimization!
getX({ y: 2, x: 1 }); // Order matters in V8!
getX({ x: 1, z: 5 });
